package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class ReproduceCVE
{
  @Test
  public void testVulnerability() throws IOException
  {
    ObjectMapper mapper = new DefaultObjectMapper();
    mapper.setInjectableValues(
        new InjectableValues.Std()
            .addValue(JavaScriptConfig.class, new JavaScriptConfig(false)) // inject disabled config
    );

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"function\": \"function(x) { return true; }\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    try {
        JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);

        // If vulnerability exists, the filter will think JS is enabled
        // because the "" property overwrote the injected config.
        filter.toFilter();

        // If we reach here, the vulnerability exists
        Assert.fail("Vulnerability reproduced: JavaScriptDimFilter allowed execution despite disabled config!");
    } catch (IllegalStateException e) {
        if ("JavaScript is disabled".equals(e.getMessage())) {
             // Expected behavior if patched
             System.out.println("Patched behavior: JavaScript is disabled.");
        } else {
             throw e;
        }
    } catch (Exception e) {
        // Any other exception might mean the deserialization failed (which is also good, effectively patched)
        // or something else went wrong.
        e.printStackTrace();
    }
  }
}

